76		if (unlikely(NAPI_GRO_CB(skb)->is_flist)) {
77			skb_shinfo(skb)->gso_type |= SKB_GSO_FRAGLIST | SKB_GSO_TCPV6;
78			skb_shinfo(skb)->gso_segs = NAPI_GRO_CB(skb)->count;
